  "mechanics": [
    {
      "id": "level-cap",
      "title": "Plafond de niveau",
      "summary": "Le plafond progresse avec les victoires majeures. Une fois atteint, chaque gain est réduit à 1 point d’expérience.",
      "details": [
        "Départ : niveau 17",
        "Puis : 27, 36, 42, 50, 56, 70, 75, 80, 85 et 94",
        "Fin de progression : niveau 100"
      ]
    },
    {
      "id": "iv",
      "title": "IV et statistiques",
      "summary": "Chaque statistique possède un IV compris entre 0 et 31. Plus il est élevé, plus le potentiel naturel du Pokémon est important.",
      "details": [
        "Un IV est fixé à la création du Pokémon.",
        "La formule du jeu utilise directement l’IV avec les statistiques de base, le niveau et les EV.",
        "Dans le Pocodex, la couleur des étoiles donne une indication de leur qualité."
      ]
    },
    {
      "id": "ev",
      "title": "EV et entraînement",
      "summary": "Un Pokémon peut cumuler 510 EV au total, avec un maximum de 252 dans une même statistique.",
      "details": [
        "Chaque tranche de 4 EV intervient dans le calcul de la statistique.",
        "Le Bracelet Macho double les EV gagnés.",
        "Les objets Pouvoir ajoutent 8 EV dans leur statistique.",
        "Le Pokérus double les EV, même après guérison."
      ]
    },
    {
      "id": "friendship",
      "title": "Bonheur et affinité",
      "summary": "Le bonheur varie de 0 à 255. Les évolutions par bonheur demandent au moins 220.",
      "details": [
        "Tous les 128 pas, chaque Pokémon valide de l’équipe a 50 % de chances de gagner du bonheur.",
        "Monter de niveau, les vitamines, certaines baies et le toilettage augmentent le bonheur.",
        "La Luxe Ball ajoute 1 aux gains concernés ; le Grelot Zen les multiplie par 1,5.",
        "Un K.O. et les remèdes amers peuvent faire baisser le bonheur."
      ]
    },
    {
      "id": "mega-evolution",
      "title": "Méga-Évolution et Lien",
      "summary": "Le texte du jeu parle de Lien, mais la vérification technique repose sur la Méga-Gemme compatible et l’accès à la Méga-Évolution.",
      "details": [
        "Une seule Méga-Évolution peut être enregistrée par dresseur et par combat.",
        "Le Pokémon doit posséder une forme Méga valide.",
        "Le bonheur n’est pas contrôlé par le code au moment de la transformation."
      ]
    },
    {
      "id": "day-night",
      "title": "Jour et nuit",
      "summary": "Le cycle n’est pas forcément visible à l’écran, mais le jeu utilise l’heure de l’ordinateur.",
      "details": [
        "Certaines évolutions ne fonctionnent que de jour ou de nuit.",
        "Modifier l’heure du système peut donc modifier la condition reconnue par le jeu."
      ]
    },
    {
      "id": "technical-machines",
      "title": "CT réutilisables",
      "summary": "Les CT sont configurées comme utilisables à l’infini dans cette version.",
      "details": [
        "Une CT n’est pas consommée après apprentissage.",
        "La compatibilité est propre aux données de Pokémon Z et peut différer des jeux officiels."
      ]
    },
    {
      "id": "field-moves",
      "title": "Capacités de terrain",
      "summary": "Les actions de terrain restent soumises à la progression, même lorsque leur accès passe par un outil ou une monture.",
      "details": [
        "Coupe et Éclate-Roc : 1 victoire majeure",
        "Flash : 2",
        "Surf : 5",
        "Plongée : 7",
        "Cascade : 8"
      ]
    }
  ],
